    static long solve(long w, long h) {
        long min = Long.MAX_VALUE;
        for (int i=1; i<h; i++) {
            long a = w*i;
            long b, c = 0, 0;
            if (w%2==0) {
                b = w/2*(h-i);
                c = b;
            }
            min = Math.min(min, Math.max(a, Math.max(b, c)) - Math.min(a, Math.min(b, c)); 
        } else if ((h-i)%2==0) {
            b = w*((h-i)/2);
            c = b;
            min = Math.min(min, Math.max(a, Math.max(b, c)) - Math.min(a, Math.min(b, c)); 
        } else {
            b = w*((h-i)/2);
            c = w*((h-i)/2+1);
